import unittest
from candidate import digitSum

class TestDigitSum(unittest.TestCase):
    def test_digitSum_empty_string(self):
        self.assertEqual(digitSum(""), 0)

    def test_digitSum_single_uppercase(self):
        self.assertEqual(digitSum("A"), 65)

    def test_digitSum_single_lowercase(self):
        self.assertEqual(digitSum("a"), 0)

    def test_digitSum_mixed_case(self):
        self.assertEqual(digitSum("abAB"), 131)

    def test_digitSum_multiple_uppercase(self):
        self.assertEqual(digitSum("ABC"), 195)

    def test_digitSum_multiple_lowercase(self):
        self.assertEqual(digitSum("abc"), 0)

    def test_digitSum_none_input(self):
        with self.assertRaises(TypeError):
            digitSum(None)

    def test_digitSum_non_string_input(self):
        with self.assertRaises(TypeError):
            digitSum(123)

if __name__ == '__main__':
    unittest.main()
